inline const RFB *GetRFB(const void *buf) {
  return ::flatbuffers::GetRoot<RFB>(buf);
}

inline const RFB *GetSizePrefixedRFB(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<RFB>(buf);
}

inline const char *RFBIdentifier() {
  return "$RFB";
}

inline bool RFBBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, RFBIdentifier());
}

inline bool SizePrefixedRFBBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, RFBIdentifier(), true);
}

template <bool B = false>
inline bool VerifyRFBBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<RFB>(RFBIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedRFBBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<RFB>(RFBIdentifier());
}

inline void FinishRFBBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<RFB> root) {
  fbb.Finish(root, RFBIdentifier());
}

inline void FinishSizePrefixedRFBBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<RFB> root) {
  fbb.FinishSizePrefixed(root, RFBIdentifier());
}

inline std::unique_ptr<RFBT> UnPackRFB(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<RFBT>(GetRFB(buf)->UnPack(res));
}

inline std::unique_ptr<RFBT> UnPackSizePrefixedRFB(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<RFBT>(GetSizePrefixedRFB(buf)->UnPack(res));
}

